t prop is set."}], "svgDesc": "Schematic of the Audio component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamAudio", "rootClass": "origam-audio", "figcaption": "Anatomy of <code>&lt;origam-audio&gt;</code> — 5 internal parts. The hidden <code>&lt;audio&gt;</code> element (⓪) drives state; the visual shell is a flex column: cover ①, metadata header ②, waveform ③, transport controller ④, optional playlist ⑤.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-audio---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.audio.css_vars.background_color", "descriptionFallback": "Player surface background."}, {"name": "--origam-audio---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.audio.css_vars.color", "descriptionFallback": "Default foreground color (text and icons)."}, {"name": "--origam-audio---accent-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.audio.css_vars.accent_color", "descriptionFallback": "Accent color driving scrubbers, play-button surface and active-loop pill."}, {"name": "--origam-audio---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.audio.css_vars.border_color", "descriptionFallback": "Player container border color."}, {"name": "--origam-audio---border-radius", "defaultValue": "{radius.lg}", "descriptionKey": "components.audio.css_vars.border_radius", "descriptionFallback": "Player container border-radius."}, {"name": "--origam-audio---gap", "defaultValue": "{space.4}", "descriptionKey": "components.audio.css_vars.gap", "descriptionFallback": "Gap between header, waveform and controller sections."}, {"name": "--origam-audio---padding", "defaultValue": "{space.4}", "descriptionKey": "components.audio.css_vars.padding", "descriptionFallback": "Padding of the player container."}, {"name": "--origam-audio__cover---size", "defaultValue": "96px", "descriptionKey": "components.audio.css_vars.cover_size", "descriptionFallback": "Cover image size in expanded variant. 48 px in compact."}, {"name": "--origam-audio__waveform---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.audio.css_vars.waveform_color", "descriptionFallback": "Played waveform bar color."}], "exposed": [{"name": "audioRef", "type": "Ref<HTMLAudioElement | null>", "descriptionKey": "components.audio.exposed.audio_ref", "descriptionFallback": "Reference to the underlying <audio> element."}, {"name": "state", "type": "IMediaPlayerState", "descriptionKey": "components.audio.exposed.state", "descriptionFallback": "Reactive playback state object: playing, paused, currentTime, duration, buffered, volume, muted, playbackRate, loading, error."}, {"name": "methods", "type": "IMediaPlayerMethods", "descriptionKey": "components.audio.exposed.methods", "descriptionFallback": "Imperative player methods: play(), pause(), seek(t), setVolume(v), setMuted(b), setPlaybackRate(r)."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "expanded", "value": "expanded"}, {"label": "compact", "value": "compact"}], "labelKey": "components.audio.playground.variant", "defaultValue": "expanded", "labelFallback": "Variant"}, {"kind": "text", "prop": "title", "labelKey": "components.audio.playground.title", "defaultValue": "Podcast Episode 42", "labelFallback": "Title"}, {"kind": "text", "prop": "artist", "labelKey": "components.audio.playground.artist", "defaultValue": "Origam Talks", "labelFallback": "Artist"}, {"kind": "switch", "prop": "waveform", "labelKey": "components.audio.playground.waveform", "defaultValue": false, "labelFallback": "Waveform"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.audio.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "downloadable", "labelKey": "components.audio.playground.downloadable", "defaultValue": false, "labelFallback": "Downloadable"}]}, "previewVariants": [{"label": "expanded", "props": {"src": "/audio/sample.mp3", "title": "Sample Track", "artist": "Artist", "variant": "expanded"}}, {"label": "compact", "props": {"src": "/audio/sample.mp3", "title": "Compact Mode", "artist": "Artist", "variant": "compact"}}, {"label": "primary", "props": {"src": "/audio/sample.mp3", "color": "primary", "title": "Primary Color", "variant": "expanded"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
