am-avatar__icon\">\n      <origam-icon :icon=\"icon\" />\n    </div>\n\n    <!-- Text/initials mode (when no image or icon) -->\n    <div class=\"origam-avatar__text\">\n      <span>{{ text }}</span>\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-avatar", "num": 1, "descriptionKey": "components.avatar.anatomy.root", "descriptionFallback": "Root element. Circle by default via <code>border-radius: {radius.full}</code>. Size tokens set <code>height</code> and <code>width</code>."}, {"cls": ".origam-avatar__wrapper", "num": 2, "descriptionKey": "components.avatar.anatomy.wrapper", "descriptionFallback": "Inner flex container (<code>inline-flex; align-items: center; justify-content: center</code>). Fills 100% of the root."}, {"cls": ".origam-avatar__image", "num": 3, "descriptionKey": "components.avatar.anatomy.image", "descriptionFallback": "Image container. Present only when <code>hasImage</code>. Wraps <code>OrigamImg</code> with <code>overflow: hidden; border-radius: inherit</code>. Creates a stacking context for the negative z-index on the inner img."}, {"cls": ".origam-avatar__icon / .origam-avatar__text", "num": 4, "descriptionKey": "components.avatar.anatomy.icon_text", "descriptionFallback": "Fallback content zones. <code>__icon</code> wraps <code>OrigamIcon</code>; <code>__text</code> wraps a <code>&lt;span&gt;</code> with initials. Mutually exclusive with the image zone."}], "classes": [{"cls": "origam-avatar", "descriptionKey": "components.avatar.anatomy.root", "descriptionFallback": "Root element. Full circle by default."}, {"cls": "origam-avatar__wrapper", "descriptionKey": "components.avatar.anatomy.wrapper", "descriptionFallback": "Inner centering flex container."}, {"cls": "origam-avatar__image", "descriptionKey": "components.avatar.anatomy.image", "descriptionFallback": "Image container with overflow hidden and border-radius inherit."}, {"cls": "origam-avatar__icon", "descriptionKey": "components.avatar.anatomy.icon", "descriptionFallback": "Icon container (fallback when no image)."}, {"cls": "origam-avatar__text", "descriptionKey": "components.avatar.anatomy.text", "descriptionFallback": "Initials/text container (fallback when no image or icon)."}], "svgDesc": "Schematic of the Avatar component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamAvatar", "rootClass": "origam-avatar", "figcaption": "Anatomy of <code>&lt;origam-avatar&gt;</code> — 4 internal parts. Content priority: <code>image</code> wins over <code>icon</code> wins over <code>text</code>.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-avatar---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.avatar.css_vars.background_color", "descriptionFallback": "Avatar background when no image is shown. Overridden by bgColor prop and status."}, {"name": "--origam-avatar---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.avatar.css_vars.color", "descriptionFallback": "Foreground (icon/text) color. Overridden by color prop and status."}, {"name": "--origam-avatar---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.avatar.css_vars.border_radius", "descriptionFallback": "Border radius. Full circle by default; overridden by the rounded prop."}, {"name": "--origam-avatar---height", "defaultValue": "40px", "descriptionKey": "components.avatar.css_vars.height", "descriptionFallback": "Avatar height. Set per size variant (24 / 32 / 40 / 48 / 56px)."}, {"name": "--origam-avatar---width", "defaultValue": "40px", "descriptionKey": "components.avatar.css_vars.width", "descriptionFallback": "Avatar width. Set per size variant (same as height)."}, {"name": "--origam-avatar---density", "defaultValue": "0px", "descriptionKey": "components.avatar.css_vars.density", "descriptionFallback": "Density offset subtracted from height and width. compact=+8px, comfortable=-8px."}, {"name": "--origam-avatar---font-size", "defaultValue": "{font.size.3xl}", "descriptionKey": "components.avatar.css_vars.font_size", "descriptionFallback": "Icon/text font size. Set per size variant."}, {"name": "--origam-avatar---box-shadow", "defaultValue": "{shadow.none}", "descriptionKey": "components.avatar.css_vars.box_shadow", "descriptionFallback": "Avatar box shadow. Changed to {shadow.md} when elevation is set."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.avatar.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.avatar.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed avatarStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.avatar.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.avatar.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.avatar.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.avatar.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.avatar.playground.bg_color", "defaultValue": "primary", "labelFallback": "Background