cy=\"62\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"248\" y=\"66.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"38\" y1=\"46\" x2=\"80\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"monospace\">origam-avatar-group</text>\n  <line x1=\"80\" y1=\"52\" x2=\"80\" y2=\"32\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"95\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"monospace\">__item (×N)</text>\n  <line x1=\"248\" y1=\"52\" x2=\"248\" y2=\"32\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"263\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"monospace\">__rest (+N chip)</text>\n  <text x=\"280\" y=\"162\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Avatars overlap via negative margin; __rest is always last.</text>\n", "code": "<div class=\"origam-avatar-group origam-avatar-group--horizontal\" role=\"group\">\n  <!-- #avatar slot × N (visible items) -->\n  <origam-avatar class=\"origam-avatar-group__item\" />\n  <origam-avatar class=\"origam-avatar-group__item\" />\n  <origam-avatar class=\"origam-avatar-group__item\" />\n\n  <!-- #rest slot — shown when items.length > max -->\n  <origam-avatar class=\"origam-avatar-group__rest\">\n    <!-- #default slot — renders \"+N\" label -->\n    +2\n  </origam-avatar>\n</div>", "legend": [{"cls": ".origam-avatar-group", "num": 1, "descriptionKey": "components.avatar_group.anatomy.root", "descriptionFallback": "Root element. Renders as an inline-flex container with <code>role=\"group\"</code>. Direction modifier class controls flex-direction."}, {"cls": ".origam-avatar-group__item", "num": 2, "descriptionKey": "components.avatar_group.anatomy.item", "descriptionFallback": "Each visible avatar. Receives a negative margin-inline-start (horizontal) or margin-block-start (vertical) to create the overlap stack effect."}, {"cls": ".origam-avatar-group__rest", "num": 3, "descriptionKey": "components.avatar_group.anatomy.rest", "descriptionFallback": "Overflow avatar showing the +N count. Visible only when items.length > max. Same overlap margin as __item."}], "classes": [{"cls": "origam-avatar-group", "descriptionKey": "components.avatar_group.anatomy.root", "descriptionFallback": "Root element. inline-flex wrapper with role=\"group\"."}, {"cls": "origam-avatar-group__item", "descriptionKey": "components.avatar_group.anatomy.item", "descriptionFallback": "Each visible avatar with negative overlap margin."}, {"cls": "origam-avatar-group__rest", "descriptionKey": "components.avatar_group.anatomy.rest", "descriptionFallback": "Overflow +N chip avatar shown when items exceed max."}, {"cls": "origam-avatar-group--horizontal", "descriptionKey": "components.avatar_group.anatomy.horizontal", "descriptionFallback": "Stacks avatars left-to-right with negative margin-inline-start."}, {"cls": "origam-avatar-group--vertical", "descriptionKey": "components.avatar_group.anatomy.vertical", "descriptionFallback": "Stacks avatars top-to-bottom with negative margin-block-start."}, {"cls": "origam-avatar-group--expand-on-hover", "descriptionKey": "components.avatar_group.anatomy.expand_on_hover", "descriptionFallback": "Applied when expandOnHover=true. Margins animate to 0 on :hover."}, {"cls": "origam-avatar-group--expand-on-click", "descriptionKey": "components.avatar_group.anatomy.expand_on_click", "descriptionFallback": "Applied when expandOnClick=true. cursor:pointer; toggled by click."}], 