ion\">\n      <origam-pagination show-first-last-page rounded />\n    </div>\n    <!-- #append slot -->\n  </origam-row>\n</div>", "legend": [{"cls": ".origam-data-table-footer__items-per-page", "num": 1, "descriptionKey": "components.data_table_footer.anatomy.items_per_page", "descriptionFallback": "Items-per-page label + OrigamSelect dropdown. Fires setItemsPerPage() on change."}, {"cls": ".origam-data-table-footer__info", "num": 2, "descriptionKey": "components.data_table_footer.anatomy.info", "descriptionFallback": "Localised page range label: \"start–stop of total\". Driven by usePagination()."}, {"cls": ".origam-data-table-footer__pagination", "num": 3, "descriptionKey": "components.data_table_footer.anatomy.pagination", "descriptionFallback": "OrigamPagination with density=\"compact\", showFirstLastPage and rounded. Syncs currentPage with the shared pagination context."}], "classes": [{"cls": "origam-data-table-footer", "descriptionKey": "components.data_table_footer.anatomy.root", "descriptionFallback": "Root element — flex row, justify-content: flex-end."}, {"cls": "origam-data-table-footer__items-per-page", "descriptionKey": "components.data_table_footer.anatomy.items_per_page", "descriptionFallback": "Container for the items-per-page label and select control."}, {"cls": "origam-data-table-footer__info", "descriptionKey": "components.data_table_footer.anatomy.info", "descriptionFallback": "Page range information label (e.g. \"1–10 of 50\")."}, {"cls": "origam-data-table-footer__pagination", "descriptionKey": "components.data_table_footer.anatomy.pagination", "descriptionFallback": "Wrapper for the embedded OrigamPagination control."}], "svgDesc": "Schematic of the footer bar with items-per-page select, page info and pagination.", "svgTitle": "Anatomy of OrigamDataTableFooter", "rootClass": "origam-data-table-footer", "figcaption": "Anatomy of <code>&lt;origam-data-table-footer&gt;</code> — 3 internal parts: items-per-page, page info label and pagination.",