INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('08e85f5b-5559-45b0-8dd3-1a994e2856d1', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'component', 'data-table-headers', 'DataTableHeaders', 'Data Display', NULL, 'mdi-table-row', 'components.catalog.data_table_headers.description', 'Header row container that renders all column header cells, an optional progress loader, and switches to mobile layout when the breakpoint is reached.', NULL, NULL, 'origam-data-table-headers', NULL, 'packages/ds/src/components/DataTable/OrigamDataTableHeaders.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', 'data-table', '{"a11y": {"notes": [{"noteKey": "components.data_table_headers.a11y.aria_sort", "noteFallback": "Each sortable header cell exposes <code>aria-sort</code> (\"ascending\", \"descending\", or \"none\") on the <code>&lt;th&gt;</code> element."}, {"noteKey": "components.data_table_headers.a11y.loader_note", "noteFallback": "When loading, the progress row is inserted inside a <code>&lt;thead&gt;</code> scope, giving screen readers the context that loading is related to the table header."}], "roles": ["rowgroup"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table_headers.a11y.key_tab", "actionFallback": "Moves focus through sortable header cells and the select-all checkbox."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-data-table__header---background-color", "descriptionKey": "components.data_table_headers.tokens.background_color", "descriptionFallback": 