"year\" />\n\n    <!-- OR view: months -->\n    <origam-date-picker-months v-model:month=\"month\" :year=\"year\" />\n\n    <!-- OR view: years -->\n    <origam-date-picker-years v-model:year=\"year\" />\n  </origam-fade>\n\n  <!-- slot: #actions -->\n  <template #actions>\n    <origam-btn text=\"Cancel\" variant=\"text\" />\n    <origam-btn text=\"OK\" color=\"primary\" />\n  </template>\n</origam-picker>", "legend": [{"cls": ".origam-date-picker", "num": 1, "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root element. Fixed width 328px (368px with showWeek). Built on OrigamPicker with overflow:hidden. Modifier --year / --months applied while switching view."}, {"cls": "OrigamDatePickerHeader", "num": 2, "descriptionKey": "components.date_picker.anatomy.header", "descriptionFallback": "Coloured header strip (background from header.background-color token = color.action.primary.bg). Shows the selected date. Hidden via hideHeader prop. Replaced by the #header slot."}, {"cls": "OrigamDatePickerControls", "num": 3, "descriptionKey": "components.date_picker.anatomy.controls", "descriptionFallback": "Navigation bar with prev/next arrow buttons and a text button that toggles between month, months and year views."}, {"cls": "OrigamDatePickerMonth", "num": 4, "descriptionKey": "components.date_picker.anatomy.month", "descriptionFallback": "Day-grid view. Weekday labels row + 6 rows of day buttons. Day cells use day.size (40px) and day.border-radius (full). Animated via OrigamFade when switching views."}, {"cls": "#actions slot", "num": 5, "descriptionKey": "components.date_picker.anatomy.actions", "descriptionFallback": "Optional action buttons row. Use for Cancel / OK confirmation pattern. Only rendered when the #actions slot is provided."}], "classes": [{"cls": "origam-date-picker", "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root picker element."}, {"cls": "origam-date-picker--month", "descriptionKey": "components.date_picker.anatomy.month_modifier", "descriptionFallback": "Applied when viewMode=\"month\". Modifier drives CSS transitions on sub-components."}, {"cls": "origam-date-picker--show-week", "descriptionKey": "components.date_picker.anatomy.show_week_modifier", "descriptionFallback": "Applied when showWeek=true. Widens the picker to 368px."}], "svgDesc": "Schematic of the DatePicker component with numbered internal regions.", "svgTitle": "Anatomy of OrigamDatePicker", "rootClass": "origam-date-picker", "figcaption": "Anatomy of <code>&lt;origam-date-picker&gt;</code> — 5 regions: root ①, header strip ②, navigation controls ③, day grid ④, and optional actions ⑤.", "svgViewBox": "0 0 700 360"}, "cssVars": [{"name": "--origam-date-picker---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.date_picker.css_vars.background_color", "descriptionFallback": "Picker surface background colour."}, {"name": "--origam-date-picker---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.date_picker.css_vars.color", "descriptionFallback": "Picker surface foreground colour."}, {"name": "--origam-date-picker---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.date_picker.css_vars.border_radius", "descriptionFallback": "Picker surface border-radius."}, {"name": "--origam-date-picker__header---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker.css_vars.header_background_color", "descriptionFallback": "Header strip background (selected-date display area)."}, {"name": "--origam-date-picker__header---color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.date_picker.css_vars.header_color", "descriptionFallback": "Header strip text colour."}, {"name": "--origam-date-picker__day---size", "defaultValue": "40px", "descriptionKey": "components.date_picker.css_vars.day_size", "descriptionFallback": "Size (width and height) of day buttons in the day grid."}, {"name": "--origam-date-picker__day---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.date_picker.css_vars.day_border_radius", "descriptionFallback": "Border-radius of day buttons (full circle by default)."}, {"name": "--origam-date-picker__day---background-color-selected", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker.css_vars.day_background_color_selected", "descriptionFallback": "Background of the selected day button."}, {"name": "--origam-date-picker__day---background-color-in-range", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.date_picker.css_vars.day_background_color_in_range", "descriptionFallback": "Background of days within a selected date range."}, {"name": "--origam-date-picker__day---color-out-of-month", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.date_picker.css_vars.day_color_out_of_month", "descriptionFallback": "Text colour of days outside the current month."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.date_picker.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.date_picker.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker.playground.range", "defaultValue": false, "labelFallback": "Range"}, {"kind": "switch", "prop": "hideHeader", "labelKey": "components.date_picker.playground.hide_header", "defaultValue": false, "labelFallback": "Hide header"}, {"kind": "switch", "prop": "showWeek", "labelKey": "components.date_picker.playground.show_week", "defaultValue": false, "labelFallback": "Show week numbers"}, {"kind": "switch", "prop": "landscape", "labelKey": "components.date_picker.playground.landscape", "defaultValue": false, "labelFallback": "Landscape"}]}, "previewVariants": [{"label": "default", "props": {"color": "primary"}}, {"label": "range", "props": {"color": "primary", "range": true}}, {"label": "no header", "props": {"color": "primary", "hideHeader": true}}, {"label": "landscape", "props": {"color": "primary", "landscape": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
