der---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"430\" y=\"128\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-layout__wrapper</text>\n  <text x=\"430\" y=\"145\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">→ origam-main + slot content</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"192\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"192\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<div :id=\"layoutId\" ref=\"origamLayoutRef\" class=\"origam-layout\">\n  <div :id=\"`${layoutId}-wrapper`\" class=\"origam-layout__wrapper\">\n    <slot name=\"default\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-layout", "num": 1, "descriptionKey": "components.layout.anatomy.root", "descriptionFallback": "Root <code>&lt;div&gt;</code>. Emits <code>--origam-layout---position-{top,right,bottom,left}</code> CSS vars reflecting each registered item''s reserved space."}, {"cls": ".origam-layout__wrapper", "num": 2, "descriptionKey": "components.layout.anatomy.wrapper", "descriptionFallback": "Inner wrapper — <code>width: 100%; height: 100%</code>. In <code>full-height</code> mode switches to <code>100vw / 100vh</code>."}], "classes": [{"cls": "origam-layout", "descriptionKey": "components.layout.anatomy.root", "descriptionFallback": "Root element. position: relative; width: 100%; height: 100%."}, {"cls": "origam-layout__wrapper", "descriptionKey": "components.layout.anatomy.wrapper", "descriptionFallback": "Inner wrapper. width: 100%; height: 100%; max-height: 100%; ma