red internal parts.", "svgTitle": "Anatomy of OrigamLabel", "rootClass": "origam-label", "figcaption": "Anatomy of <code>&lt;origam-label&gt;</code> — 2 internal parts. The required indicator ② is a <code>&lt;sup&gt;*&lt;/sup&gt;</code> appended when <code>required=true</code>.", "svgViewBox": "0 0 500 160"}, "cssVars": [{"name": "--origam-label---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.label.css_vars.color", "descriptionFallback": "Default label text color."}, {"name": "--origam-label---font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.label.css_vars.font_size", "descriptionFallback": "Default font size. Overridden to 1em when used inside OrigamField."}, {"name": "--origam-label---font-weight", "defaultValue": "{font.weight.regular}", "descriptionKey": "components.label.css_vars.font_weight", "descriptionFallback": "Label font weight."}, {"name": "--origam-label---line-height", "defaultValue": "{font.lineHeight.normal}", "descriptionKey": "components.label.css_vars.line_height", "descriptionFallback": "Label line height."}, {"name": "--origam-label---letter-spacing", "defaultValue": "{font.letterSpacing.normal}", "descriptionKey": "components.label.css_vars.letter_spacing", "descriptionFallback": "Label letter spacing."}, {"name": "--origam-label---pointer-events", "defaultValue": "none", "descriptionKey": "components.label.css_vars.pointer_events", "descriptionFallback": "Labels do not capture pointer events (positioned on top of input)."}, {"name": "--origam-label---transition-duration", "defaultValue": "{motion.duration.normal}", "descriptionKey": "components.label.css_vars.transition_duration", "descriptionFallback": "Duration of opacity/transform transitions for the float animation."}, {"name": "--origam-label---required-indicator-color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.label.css_vars.required_indicator_color", "descriptionFallback": "Color of the asterisk required indicator <sup>*</sup>."}, {"name": "--origam-label__floating---font-size", "defaultValue": "0.75em", "descriptionKey": "components.label.css_vars.floating_font_size", "descriptionFallback": "Font size of the floating variant (clone shown in the field notch)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.label.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.label.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.label.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.label.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.label.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.label.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "required", "labelKey": "components.label.playground.required", "defaultValue": false, "labelFallback": "Required"}, {"kind": "switch", "prop": "floating", "labelKey": "components.label.playground.floating", "defaultValue": false, "labelFallback": "Floating"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.label.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "tag", "options": [{"label": "label", "value": "label"}, {"label": "span", "value": "span"}, {"label": "legend", "value": "legend"}], "labelKey": "components.label.playground.tag", "defaultValue": "label", "labelFallback": "Tag"}], "defaultSlotContent": "Email address"}, "previewVariants": [{"label": "default", "props": {}, "slotContent": "Email address"}, {"label": "required", "props": {"required": true}, "slotContent": "Password"}, {"label": "primary", "props": {"color": "primary"}, "slotContent": "Username"}, {"label": "danger", "props": {"color": "danger", "required": true}, "slotContent": "Error field"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
