INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d290470e-acfe-4509-9b8a-929c5710bacf', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'component', 'slide-x', 'SlideX', 'Utilities & Providers', NULL, 'mdi-arrow-left-right', 'components.catalog.transition_slide_x.description', 'CSS-driven Vue transition that slides a child element horizontally (translateX −15px → identity) combined with an opacity fade. Sub-component of the Transition family.', NULL, NULL, 'origam-slide-x', NULL, 'packages/ds/src/components/Transition/OrigamSlideX.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.slide_x.a11y.reduced_motion", "noteFallback": "Animation is disabled automatically when prefers-reduced-motion: reduce is detected (disabled=true via useCssTransition)."}, {"noteKey": "components.slide_x.a11y.no_role", "noteFallback": "The wrapper is transparent to the accessibility tree. Only the slotted child is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"83\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">translateX(−15px) → 0</text>\n  <text x=\"170\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 0 → 1</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"530\" y=\"83\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">0 → translateX(−15px)</text>\n  <text x=\"530\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 1 → 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"95\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- wraps <transition> or <transition-group> via useCssTransition -->\n<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>\n\n<!-- CSS (global, not scoped) -->\n<!-- .origam-transition--slide-x-enter-from,\n     .origam-transition--slide-x-leave-to { opacity: 0; transform: translateX(-15px); }\n     .origam-transition--slide-x-enter-active,\n     .origam-transition--slide-x-leave-active { transition-property: transform, opacity; transition-duration: 0.3s; } -->", "legend": [{"cls": ".origam-transition--slide-x-enter-active", "num": 1, "descriptionKey": "components.slide_x.anatomy.enter", "descriptionFallback": "Enter phase. Child animates from translateX(−15px) + opacity:0 to identity. Duration: 0.3 s, easing: cubic-bezier(0.4,0,0.2,1)."}, {"cls": ".origam-transition--slide-x-leave-active", "num": 2, "descriptionKey": "components.slide_x.anatomy.leave", "descriptionFallback": "Leave phase. Child slides back to translateX(−15px) + opacity:0 over 0.3 s."}], "classes": [{"cls": "origam-transition--slide-x", "descriptionKey": "components.slide_x.anatomy.class_root", "descriptionFallback": "CSS transition class prefix applied by Vue."}, {"cls": "origam-transition--slide-x-enter-from", "descriptionKey": "components.slide_x.anatomy.class_enter_from", "descriptionFallback": "Starting state: opacity:0, transform: translateX(−15px)."}, {"cls": "origam-transition--slide-x-leave-to", "descriptionKey": "components.slide_x.anatomy.class_leave_to", "descriptionFallback": "End state on leave: same as enter-from (symmetric)."}, {"cls": "origam-transition--slide-x-enter-active", "descriptionKey": "components.slide_x.anatomy.class_enter_active", "descriptionFallback": "Active enter: transitions transform and opacity over 0.3 s."}, {"cls": "origam-transition--slide-x-leave-active", "descriptionKey": "components.slide_x.anatomy.class_leave_active", "descriptionFallback": "Active leave: transitions transform and opacity over 0.3 s."}, {"cls": "origam-transition--slide-x-move", "descriptionKey": "components.slide_x.anatomy.class_move", "descriptionFallback": "Move transition in group mode: transform only, 0.5 s."}], "svgDesc": "Schematic o