INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1ee5d1c7-6efe-4e94-b871-17bb55c22197', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'component', 'snackbar-group', 'SnackbarGroup', 'Feedback & Status', NULL, 'mdi-message-badge-outline', 'components.catalog.snackbar_group.description', 'Manages a queue of toast notifications stacked at a viewport anchor, driven by the useSnackbarGroup composable.', NULL, NULL, 'origam-snackbar-group', NULL, 'packages/ds/src/components/Snackbar/OrigamSnackbarGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-snackbar--design', '/docs/components/Snackbar/OrigamSnackbar.html', 'snackbar', '{"a11y": {"notes": [{"noteKey": "components.snackbar_group.a11y.region_note", "noteFallback": "The stack root carries role=\"region\" and aria-label=\"Notifications\" so screen readers can navigate to the announcement zone."}, {"noteKey": "components.snackbar_group.a11y.live_note", "noteFallback": "Each SnackbarItem inside the group carries aria-live=\"polite\" (info, success) or aria-live=\"assertive\" (warning, danger) so announcements are prioritised correctly."}, {"noteKey": "components.snackbar_group.a11y.reduced_motion_note", "noteFallback": "Slide transitions are replaced by an opacity-only fade under prefers-reduced-motion: reduce."}], "roles": ["region", "status", "alert"], "keyboard": [{"key": "Tab", "actionKey": "components.snackbar_group.a11y.key_tab", "actionFallback": "Moves focus to the dismiss button or action buttons inside the visible toast items."}, {"key": "Enter / Space", "actionKey": "components.snackbar_group.a11y.key_activate", "actionFallback": "Activates the focused dismiss or action button."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-snackbar-group---gap", "descriptionKey": "components.snackbar_group.tokens.gap", "descriptionFallback": "Gap between stacked toast items."}, {"type": "dimension", "value": "420px", "tokenPath": "--origam-snackbar-group---max-width", "descriptionKey": "components.snackbar_group.tokens.max_width", "descriptionFallback": "Maximum width of the stack container."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-snackbar-group---transition-duration", "descriptionKey": "components.snackbar_group.tokens.transition_duration", "descriptionFallback": "Duration of the enter/leave slide transitions."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-snackbar-group---position-top", "descriptionKey": "components.snackbar_group.tokens.position_top", "descriptionFallback": "Distance from the top edge for top-* locations."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-snackbar-group---position-right", "descriptionKey": "components.snackbar_group.tokens.position_right", "descriptionFallback": "Distance from the right edge for *-right locations."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"20\" width=\"652\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"36\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-snackbar-group (Teleport → body)</text>\n  <rect x=\"36\" y=\"54\" width=\"628\" 