age text."}, {"cls": "origam-snackbar-item__actions", "descriptionKey": "components.snackbar_item.anatomy.actions", "descriptionFallback": "Action buttons row."}, {"cls": "origam-snackbar-item__dismiss", "descriptionKey": "components.snackbar_item.anatomy.dismiss", "descriptionFallback": "Close/dismiss button."}], "svgDesc": "Schematic of the SnackbarItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamSnackbarItem", "rootClass": "origam-snackbar-item", "figcaption": "Anatomy of <code>&lt;origam-snackbar-item&gt;</code> — 7 internal parts. The <code>__content</code> row holds the prepend icon and the text block; <code>__actions</code> and <code>__dismiss</code> are appended when present.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-snackbar-item---gap", "defaultValue": "12px", "descriptionKey": "components.snackbar_item.css_vars.gap", "descriptionFallback": "Gap between the prepend area and the text+actions block."}, {"name": "--origam-snackbar-item---min-width", "defaultValue": "288px", "descriptionKey": "components.snackbar_item.css_vars.min_width", "descriptionFallback": "Minimum width of the item."}, {"name": "--origam-snackbar-item---max-width", "defaultValue": "420px", "descriptionKey": "components.snackbar_item.css_vars.max_width", "descriptionFallback": "Maximum width of the item."}, {"name": "--origam-snackbar-item---padding", "defaultValue": "12px 14px", "descriptionKey": "components.snackbar_item.css_vars.padding", "descriptionFallback": "Inner padding of the item."}, {"name": "--origam-snackbar-item---border-radius", "defaultValue": "8px", "descriptionKey": "components.snackbar_item.css_vars.border_radius", "descriptionFallback": "Corner radius of the item card."}, {"name": "--origam-snackbar-item---background-color", "defaultValue": "var(--origam-color__surface---default)", "descriptionKey": "components.snackbar_item.css_vars.background_color", "descriptionFallback": "Default background. Intent variants override this via feedback tokens."}, {"name": "--origam-snackbar-item---border-color", "defaultValue": "var(--origam-color__border---subtle)", "descriptionKey": "components.snackbar_item.css_vars.border_color", "descriptionFallback": "Default border colour. Intent variants override this via feedback tokens."}, {"name": "--origam-snackbar-item---box-shadow", "defaultValue": "0 4px 12px rgba(0,0,0,0.12)", "descriptionKey": "components.snackbar_item.css_vars.box_shadow", "descriptionFallback": "Elevation shadow for the item card."}, {"name": "--origam-snackbar-item__title---font-weight", "defaultValue": "600", "descriptionKey": "components.snackbar_item.css_vars.title_font_weight", "descriptionFallback": "Font weight of the title line."}, {"name": "--origam-snackbar-item__message---opacity", "defaultValue": "0.85", "descriptionKey": "components.snackbar_item.css_vars.message_opacity", "descriptionFallback": "Opacity of the message text, giving the title visual priority."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.snackbar_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.snackbar_item.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "select", "prop": "intent", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.snackbar_item.playground.intent", "defaultValue": "", "labelFallback": "Intent"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.snackbar_item.playground.icon", "defaultValue": "", "labelFallback": "Icon"}, {"kind": "switch", "prop": "dismissible", "labelKey": "components.snackbar_item.playground.dismissible", "defaultValue": true, "labelFallback": "Dismissible"}, {"kind": "select", "prop": "ariaLive", "options": [{"label": "(default)", "value": ""}, {"label": "polite", "value": "polite"}, {"label": "assertive", "value": "assertive"}], "labelKey": "components.snackbar_item.playground.aria_live", "defaultValue": "", "labelFallback": "Aria Live"}], "defaultSlotContent": "Content"}, "previewVariants": [{"label": "info", "props": {"title": "Info", "intent": "info", "message": "This is an informational message."}}, {"label": "success", "props": {"title": "Success", "intent": "success", "message": "Operation completed successfully."}}, {"label": "warning", "props": {"intent": "warning", "message": "Something might need your attention."}}, {"label": "danger", "props": {"title": "Error", "intent": "danger", "message": "An error has occurred."}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b1cac64b-e187-45f0-b388-f37df02d47bf', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'component', 'spacer', 'Spacer', 'Layout & Structure', NULL, 'mdi-arrow-expand-horizontal', 'components.catalog.spacer.description', 'Flex spacer that grows to fill available space inside a flex row or column, pushing siblings apart.', NULL, NULL, 'origam-spacer', NULL, 'packages/ds/src/components/Grids/OrigamSpacer.vue', 'origam', NULL, NULL, '/stories/?story=components-spacer--design', '/docs/components/Spacer/OrigamSpacer.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.spacer.a11y.presentational_note", "noteFallback": "Spacer is a purely presentational layout element with no semantic role. Screen readers skip it entirely. No ARIA attributes are needed."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"32\" y=\"38\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">flex container (e.g. origam-toolbar / origam-row)</text>\n  <rect x=\"32\" y=\"48\" width=\"80\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"72\" y=\"70\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">sibling</text>\n  <rect x=\"124\" y=\"48\" width=\"432\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"5 3\"/>\n  <text x=\"340\" y=\"70\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-spacer  (flex-grow: 1)</text>\n  <rect x=\"568\" y=\"48\" width=\"80\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"608\" y=\"70\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">sibling</text>\n  <circle cx=\"132\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"132\" y=\"60\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n", "code": "<div class=\"origam-spacer\">\n  <slot />\n</div>", "legend": [{"cls": ".origam-spacer", "num": 1, "descriptionKey": "components.spacer.anatomy.root", "descriptionFallback": "Root element. <code>flex-grow: 1</code> (driven by <code>--origam-spacer---flex-grow</code>). No visual surface by default — purely a layout utility."}], "classes": [{"cls": "origam-spacer", "descriptionKey": "components.spacer.anatomy.root", "descriptionFallback": "Root element. flex-grow: 1 via --origam-spacer---flex-grow."}], "svgDesc": "Schematic of the Spacer component with 1 numbered part inside a flex container.", "svgTitle": "Anatomy of OrigamSpacer", "rootClass": "origam-spacer", "figcaption": "Anatomy of <code>&lt;origam-spacer&gt;</code> — a single element that grows to fill all remaining space in a flex container.", "svgViewBox": "0 0 700 120"}, "cssVars": [{"name": "--origam-spacer---flex-grow", "defaultValue": "1", "descriptionKey": "components.spacer.css_vars.flex_grow", "descriptionFallback": "Controls how greedily the spacer grows inside a flex container. Default is 1 (fill all remaining space)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.spacer.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.spacer.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.spacer.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.spacer.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.spacer.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.spacer.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c52ec2a2-694d-4cdb-a9ba-3906b26b39be', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'component', 'stepper', 'Stepper', 'Navigation', NULL, 'mdi-dots-horizontal-circle-outline', 'components.catalog.stepper.description', 'Visual progress indicator that guides the user through a numbered sequence of steps, supporting horizontal and vertical orientations.', NULL, NULL, 'origam-stepper', NULL, 'packages/ds/src/components/Stepper/OrigamStepper.vue', 'origam', NULL, NULL, '/stories/?story=components-stepper--design', '/docs/components/Stepper/OrigamStepper.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.stepper.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.stepper.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "select", "prop": "orientation", "options": [{"label": "(default)", "value": ""}, {"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.stepper.playground.orientation", "defaultValue": "", "labelFallback": "Orientation"}, {"kind": "switch", "prop": "clickable", "labelKey": "components.stepper.playground.clickable", "defaultValue": false, "labelFallback": "Clickable"}, {"kind": "switch", "prop": "showConnectors", "labelKey": "components.stepper.playground.show_connectors", "defaultValue": true, "labelFallback": "Show Connectors"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c049e1f3-5047-4f9f-8b9e-274abfee797e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'component', 'stepper-item', 'StepperItem', 'Navigation', NULL, 'mdi-progress-check', 'components.catalog.stepper_item.description', 'Individual step inside a Stepper. Renders an indicator circle with its status (pending / active / done / error), a title, and an optional subtitle.', NULL, NULL, 'origam-stepper-item', NULL, 'packages/ds/src/components/Stepper/OrigamStepperItem.vue', 'origam', NULL, NULL, '/stories/?story=components-stepper--design', '/docs/components/Stepper/OrigamStepper.html', 'stepper', '{"a11y": {"notes": [{"noteKey": "components.stepper_item.a11y.current_note", "noteFallback": "The active step carries aria-current=\"step\" so screen readers announce it as the current step in the sequence."}, {"noteKey": "components.stepper_item.a11y.label_note", "noteFallback": "When a title is provided, the step button receives an aria-label of the form \"Step {n}: {title}\" generated by the DS locale key origam.stepper.stepAriaLabel."}, {"noteKey": "components.stepper_item.a11y.indicator_note", "noteFallback": "The indicator circle carries aria-hidden=\"true\" — its content (number, check, exclamation) is decorative because the aria-label on the root already conveys the step identity and status."}, {"noteKey": "components.stepper_item.a11y.focus_note", "noteFallback": "Clickable items show a focus-visible outline using the stepper primary colour token. Non-clickable items have cursor: default and are not keyboard-reachable."}], "roles": ["button"], "keyboard": [{"key": "Tab", "actionKey": "components.stepper_item.a11y.key_tab", "actionFallback": "Moves focus to the next clickable step button."}, {"key": "Enter / Space", "actionKey": "components.stepper_item.a11y.key_activate", "actionFallback": "Navigates to this step when clickable is true."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---8)", "tokenPath": "--origam-stepper---indicator-size", "descriptionKey": "components.stepper_item.tokens.indicator_size", "descriptionFallback": "Width and height of the step indicator circle."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-stepper---indicator-active-bg", "descriptionKey": "components.stepper_item.tokens.indicator_active_bg", "descriptionFallback": "Background of the active step indicator."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-stepper---indicator-error-bg", "descriptionKey": "components.stepper_item.tokens.indicator_error_bg", "descriptionFallback": "Background of the error state indicator."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-stepper---title-font-weight", "descriptionKey": "components.stepper_item.tokens.title_font_weight", "descriptionFallback": "Font weight of the step title."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-stepper---subtitle-color", "descriptionKey": "components.stepper_item.tokens.subtitle_color", "descriptionFallback": "Colour of the step subtitle."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"220\" y=\"20\" width=\"260\" height=\"160\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"235\" y=\"42\" font-size=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-stepper-item</text>\n  <circle cx=\"350\" cy=\"80\" r=\"24\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <text x=\"350\" y=\"85\" font-size=\"13\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"600\" font-family=\"''JetBrains Mono'',monospace\">2</text>\n  <rect x=\"260\" y=\"118\" width=\"180\" height=\"18\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"131\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1a1a1a)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">Profile</text>\n  <rect x=\"275\" y=\"142\" width=\"150\" height=\"14\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.03))\"/>\n  <text x=\"350\" y=\"153\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Fill in your details</text>\n  <circle cx=\"228\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"228\" y=\"32\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"326\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"326\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"326\" cy=\"126\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"326\" y=\"130\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"326\" cy=\"149\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"326\" y=\"153\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<!-- renders as <button> when clickable, <div> when not -->\n<component :is=\"isClickable ? ''button'' : ''div''\"\n  class=\"origam-stepper-item origam-stepper-item--active origam-stepper-item--horizontal\"\n  aria-current=\"step\">\n  <span class=\"origam-stepper-item__indicator origam-stepper-item__indicator--active\"\n    aria-hidden=\"true\">\n    2\n  </span>\n  <span class=\"origam-stepper-item__label\">\n    <span class=\"origam-stepper-item__title\">Profile</span>\n    <span class=\"origam-stepper-item__subtitle\">Fill in your details</span>\n  </span>\n</component>", "legend": [{"cls": ".origam-stepper-item", "num": 1, "descriptionKey": "components.stepper_item.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;button type=\"button\"&gt;</code> when clickable, <code>&lt;div&gt;</code> otherwise. Carries status and orientation modifier classes."}, {"cls": ".origam-stepper-item__indicator", "num": 2, "descriptionKey": "components.stepper_item.anatomy.indicator", "descriptionFallback": "Circular badge. Shows step number (pending), a check icon (done), an exclamation icon (error), or the custom icon prop. Background and border colour are token-driven per status."}, {"cls": ".origam-stepper-item__title", "num": 3, "descriptionKey": "components.stepper_item.anatomy.title", "descriptionFallback": "Primary label. Font-weight and color driven by <code>--origam-stepper---title-*</code> tokens."}, {"cls": ".origam-stepper-item__subtitle", "num": 4, "descriptionKey": "components.stepper_item.anatomy.subtitle", "descriptionFallback": "Secondary label shown below the title. Smaller size and muted colour via <code>--origam-stepper---subtitle-*</code> tokens."}], "classes": [{"cls": "origam-stepper-item", "descriptionKey": "components.stepper_item.anatomy.root", "descriptionFallback": "Root element with status + orientation modifiers."}, {"cls": "origam-stepper-item__indicator", "descriptionKey": "components.stepper_item.anatomy.indicator", "descriptionFallback": "Circular step badge with status modifier."}, {"cls": "origam-stepper-item__label", "descriptionKey": "components.stepper_item.anatomy.label", "descriptionFallback": "Column host for title and subtitle."}, {"cls": "origam-stepper-item__title", "descriptionKey": "components.stepper_item.anatomy.title", "descriptionFallback": "Primary step label."}, {"cls": "origam-stepper-item__subtitle", "descriptionKey": "components.stepper_item.anatomy.subtitle", "descriptionFallback": "Secondary step label."}], "svgDesc": "Schematic of the StepperItem component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamStepperItem", "rootClass": "origam-stepper-item", "figcaption": "Anatomy of <code>&lt;origam-stepper-item&gt;</code> — 4 internal parts. The root renders as <code>&lt;button&gt;</code> when clickable, <code>&lt;div&gt;</code> otherwise; the indicator circle shows step number, done-check or error-exclamation.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-stepper---indicator-size", "defaultValue": "32px", "descriptionKey": "components.stepper_item.css_vars.indicator_size", "descriptionFallback": "Width and height of the step indicator circle."}, {"name": "--origam-stepper---indicator-bg", "defaultValue": "var(--origam-color__surface---overlay)", "descriptionKey": "components.stepper_item.css_vars.indicator_bg", "descriptionFallback": "Background of the pending step indicator."}, {"name": "--origam-stepper---indicator-color", "defaultValue": "var(--origam-color__text---secondary)", "descriptionKey": "components.stepper_item.css_vars.indicator_color", "descriptionFallback": "Foreground of the pending step indicator."}, {"name": "--origam-stepper---color", "defaultValue": "var(--origam-color__action--primary---bg)", "descriptionKey": "components.stepper_item.css_vars.color", "descriptionFallback": "Active/done indicator colour. Controls both the border and the background tint."}, {"name": "--origam-stepper---indicator-error-bg", "defaultValue": "var(--origam-color__feedback--danger---bg)", "descriptionKey": "components.stepper_item.css_vars.indicator_error_bg", "descriptionFallback": "Background of the error state indicator."}, {"name": "--origam-stepper---title-font-size", "defaultValue": "0.875rem", "descriptionKey": "components.stepper_item.css_vars.title_font_size", "descriptionFallback": "Font size of the step title."}, {"name": "--origam-stepper---title-font-weight", "defaultValue": "500", "descriptionKey": "components.stepper_item.css_vars.title_font_weight", "descriptionFallback": "Font weight of the step title."}, {"name": "--origam-stepper---subtitle-font-size", "defaultValue": "0.75rem", "descriptionKey": "components.stepper_item.css_vars.subtitle_font_size", "descriptionFallback": "Font size of the step subtitle."}, {"name": "--origam-stepper---subtitle-color", "defaultValue": "var(--origam-color__text---secondary)", "descriptionKey": "components.stepper_item.css_vars.subtitle_color", "descriptionFallback": "Colour of the step subtitle text."}, {"name": "--origam-stepper---gap", "defaultValue": "8px", "descriptionKey": "components.stepper_item.css_vars.gap", "descriptionFallback": "Gap between the indicator circle and the label column."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.stepper_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "resolvedStatus", "type": "ComputedRef<''pending'' | ''active'' | ''done'' | ''error''>", "descriptionKey": "components.stepper_item.exposed.resolved_