e, "labelFallback": "Fixed"}, {"kind": "switch", "prop": "centered", "labelKey": "components.tabs.playground.centered", "defaultValue": false, "labelFallback": "Centered"}, {"kind": "switch", "prop": "mandatory", "labelKey": "components.tabs.playground.mandatory", "defaultValue": true, "labelFallback": "Mandatory"}], "defaultSlotContent": "Tab"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
