INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b806a547-32dd-4bcb-8402-7839ac3efc78', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-adjacent', 'useAdjacent', NULL, 'Commons', 'mdi-arrow-expand-horizontal', '', 'Resolve the presence of prepend and append slots/icons for a component. Exposes computed flags (hasPrepend, hasAppend) that combine both the slot content and the icon/avatar props, plus click-event emitters for the clickable prepend/append areas. A companion composable useAdjacentInner handles the inner prepend/append surface (inside an input field).', NULL, 'function useAdjacent(
