INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8b368476-da98-42f9-8b52-745f926ff1bb', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-chart', 'useChart', NULL, 'Chart', 'mdi-chart-line', '', 'Stateless SVG chart engine powering <OrigamChart>. Computes every render-time descriptor needed for cartesian, polar, pie/donut, radar, bar, scatter, and stacked variants: viewBox, pixel-mapping scales, gridline ticks, per-series path/rect/circle descriptors, resolved legend entries, and an interactive hover state. Driven entirely by thunk options so it reacts to props, stores, or computed refs without re-instantiation.', NULL, 'function useChart(options: IUseChartOptions): {
