INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8b574fe4-0c27-4470-bba9-65327fde2be6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-select', 'useSelection', NULL, 'DataTable', 'mdi-checkbox-multiple-marked-outline', '', 'Inject accessor for the row-selection context provided by provideSelection inside OrigamDataTable. Returns the reactive selected Set and the select / toggleSelect / selectAll helpers plus status flags (someSelected, allSelected, showSelectAll). Used by checkbox columns and the header select-all control.', NULL, 'function useSelection(): IDataTableProvideSelection', NULL, NULL, 'packages/ds/src/composables/DataTable/select.composable.ts', NULL, NULL, 'useSelection throws when called outside a DataTable context (no inject match for ORIGAM_DATA_TABLE_SELECT_KEY). It must be used inside a component tree where provideSelection() was called by the parent table.', NULL, NULL, NULL, '{"consumedInterfaces": ["IDataTableProvideSelection", "IDataTableSelectableItem", "IDataTableSelectProps"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('38440ff1-ef53-4bf1-80c0-567271e14be9', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-select-link', 'useSelectLink', NULL, 'Commons', 'mdi-link-variant', '', 'Bridges a router link and a group selection: when the link becomes active (current route matches), it automatically selects its group item. Used internally by navigation components (NavList, BottomNav, Tabs) so that a hard navigation or a programmatic router push keeps the selected state in sync without a manual v-model update.', NULL, 'function useSelectLink(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('48191bc9-805d-4952-a274-b918016dccc2', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-ssr-boot', 'useSsrBoot', NULL, 'Commons', 'mdi-server', '', 'Defers CSS transitions until after the first browser paint to prevent flash-of-transition on SSR hydration. Returns an isBooted flag (false during SSR and the first rAF frame, then true) and a ssrBootStyles computed that injects `transition: none !important` while booting, suppressing unwanted entry animations during hydration.', NULL, 'function useSsrBoot(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('231df619-180b-4ac6-8185-97b40484596b', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-sheet-swipe', 'useSheetSwipe', NULL, 'Sheet', 'mdi-gesture-swipe-up', '', 'Encapsulates bottom-sheet swipe gesture logic using Pointer Events (covers both mouse and touch). Tracks pointerdown → pointermove → pointerup on a dedicated handle element, resolves the target snap point on release via velocity (fast flick = step one snap) or absolute distance (slow drag = nearest snap), and exposes reactive drag state for 1:1 finger tracking during the gesture.', NULL, 'function useSheetSwipe(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d1575317-2c36-4ad4-a69d-d09dc37986e6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-size', 'useSize', NULL, 'Commons', 'mdi-magnify-plus-outline', '', 'Resolves the `size` prop to component-local modifier classes and optional width/height inline styles. Named presets (x-small/small/default/large/x-large) emit BEM modifier classes; custom values emit pixel dimensions.', NULL, 'function useSize(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a3639c98-65cf-4a92-a7b7-2ef740a35da8', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-slider-field', 'useSteps', NULL, 'SliderField', 'mdi-tune-variant', '', 'Pure-function stepping math for OrigamSliderField. Computes reactive min / max / step / decimals values from the component props and exposes a roundValue helper that snaps any raw number to the nearest valid step (clamped to [min, max]). After the migration to a native <input type="range">, this is the only remaining logic layer for the slider — the browser now owns drag tracking.', NULL, 'function useSteps(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8e3955dc-0925-478e-962f-feb3a3a7a2e3', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-snackbar', 'useCountdown', NULL, 'Snackbar', 'mdi-timer-sand', '', 'Internal countdown timer used by OrigamSnackbar to drive the auto-dismiss progress indicator. Counts down from a given millisecond value using setInterval, ticking at the CSS transition duration of the host element so the progress bar remains visually synchronised. Exposes clear / reset / start controls and a reactive time ref.', NULL, 'function useCountdown(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d73e007c-3db4-44fe-893b-1c766fa0eafd', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-snackbar-group', 'useSnackbarGroup', NULL, 'Snackbar', 'mdi-bell-outline', '', 'Module-level singleton store for a named snackbar stack. Push notifications via notify(), dismiss them by id or all at once. Each call sharing the same id option reads and writes the same reactive items list — the composable and the matching <OrigamSnackbarGroup id="…"> component share live state with no event bus required.', NULL, 'function useSnackbarGroup(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('940bc82a-275c-4615-b527-7787a4ff7d62', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-snackbar-group-internal', 'useSnackbarGroupInternal', 'Snackbar', 'Snackbar', NULL, NULL, NULL, NULL, 'function useSnackbarGroupInternal(id?: MaybeRefOrGetter<string> = SNACKBAR_GROUP_DEFAULT_ID): { rawItems: ComputedRef<ISnackbarGroupItem[]>; itemCount: ComputedRef<number>; registerDefaultDuration: (duration: number) => void; }', NULL, NULL, 'packages/ds/src/composables/Snackbar/snackbarGroupInternal.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fb375c70-6ad6-42e8-9fa1-f9620a8c6058', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-sort', 'useSort', NULL, 'DataTable', 'mdi-sort', '', 'Inject accessor for the sort context provided by provideSort inside OrigamDataTable. Returns the reactive sortBy array and the toggleSort / isSorted helpers. Used by header cells to read and update the active sort columns. The companion useSortedItems applies the sort order to a reactive item list.', NULL, 'function useSort(): IDataTableProvideSort
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ff137271-22b1-4de2-a4b3-5ce8ab92af98', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-sorted-items', 'useSortedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function useSortedItems(props: { customKeySort: TDataTableCompareFunction | undefined }, items: Ref<T[]>, sortBy: Ref<Array<IDataTableSortItem>>, options?: { transform?: (item: T) => Record<string, unknown> sortFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> sortRawFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> }): { sortedItems: ComputedRef<T[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/sortedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('222c4649-61ff-44b7-a8f7-b8789e82bcfd', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-use-waveform', 'useWaveform', 'Audio', 'Audio', NULL, NULL, NULL, NULL, 'function useWaveform(srcRef: Ref<string | undefined | null>, options?: IUseWaveformOptions = {}): { peaks: Ref<Array<number>> isComputing: Ref<boolean> error: Ref<Error | null> compute: () => Promise<void> }', NULL, NULL, 'packages/ds/src/composables/Audio/use-waveform.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e29d0d56-c5cd-43ae-971b-19b424b642b6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-stack', 'useStack', NULL, 'Commons', 'mdi-layers-outline', '', 'Manages z-index stacking order for overlay components (Dialog, Menu, Tooltip, Drawer, …). Registers the component in the global GLOBAL_STACK array when it becomes active and auto-computes a z-index 10 units above the current topmost overlay. Exposes globalTop (is this the topmost overlay worldwide?) and localTop (does this overlay have no active child overlays?) for pointer-event and close-on-outside-click decisions.', NULL, 'function useStack(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('462afbd8-7a5a-4efd-b951-feda927f3bd6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-state-effect', 'useStateEffect', NULL, 'Commons', 'mdi-palette-swatch-variant', '', 'Unified composable that consolidates eight visual axes (color, bgColor, border, rounded, elevation, padding, margin, gap) into a single state-aware layer. Reads the hover / active state and their override objects (IHoverState / IActiveState) and emits per-axis classes + styles for each axis. Replaces the prior chain of useColorEffect + useBorder + useRounded + useElevation + usePadding + useMargin that every visual component had to repeat.', NULL, 'function useStateEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f4893819-67bb-4bce-9f82-d72f4dc73777', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-state-flag', 'useStateFlag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStateFlag(props: object, options: IStateFlagOptions<S>): IStateFlagReturn', NULL, NULL, 'packages/ds/src/composables/Commons/stateFlag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('51a21cda-6f3c-445f-9504-ba5b1e40735f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-status', 'useStatus', NULL, 'Commons', 'mdi-alert-circle-outline', '', 'Resolves semantic status props (success, info, warning, error) into icon slots, status classes, and a forced intent color. The status intent overrides any color / bgColor the consumer passed — a status colour is non-negotiable by design. Also manages icon routing across prepend / append / replace slots based on statusIconPosition.', NULL, 'function useStatus(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('646893bb-74cc-4ca4-92bd-474a6d291d5e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-sticky', 'useSticky', NULL, 'Commons', 'mdi-pin-outline', '', 'Implements the "sticky-while-scrolling" pattern for taller-than-viewport navigation drawers. Tracks scroll direction and element bounding rect to decide whether the sidebar is stuck at the top, stuck at the bottom, or free-floating mid-page. Returns stickyStyles with the appropriate top/bottom offset so the sidebar scrolls naturally through long content without jumping.', NULL, 'function useSticky(options: ISticky): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('258367ed-d37d-4126-b182-1cf52955ad07', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-style', 'useStyle', NULL, 'Commons', 'mdi-code-tags', '', 'Injects a dynamic <style> tag into document.head scoped to a generated element id, allowing components to apply per-instance CSS that cannot be expressed as inline styles (e.g. pseudo-element rules, :hover selectors, @keyframes). Also exposes the lower-level useStyleTag for raw CSS string injection. Both composables manage their own lifecycle: they load on mount and unload on scope dispose.', NULL, 'function useStyle(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('49b71666-acb9-41c3-81a4-565607b5ec28', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-style-tag', 'useStyleTag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStyleTag(css: MaybeRef<string>, options?: IStyleTagOptions = {}): { id: string; css: Ref<string, string> | ShallowRef<string, string> | WritableComputedRef<string, string>; unload: () => void; load: () => void; isLoaded: Readonly<...>; }', NULL, NULL, 'packages/ds/src/composables/Commons/styleTag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('04fe12ae-af59-4a66-838a-925ca63ae1f2', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-teleport', 'useTeleport', NULL, 'Commons', 'mdi-arrow-top-right-bold-box-outline', '', 'Resolves the Vue Teleport target for overlay components. Accepts true (disable teleport — render inline), false (teleport to document.body), a CSS selector string (teleport to the matched element), or a raw Element. Creates an .origam-overlay-container div inside the target when one does not already exist, so multiple overlays sharing the same target stack correctly without polluting the host''s direct children.', NULL, 'function useTeleport(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f534cd49-56ce-43d5-a80e-fb5cacb389b4', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'const', 'block-array', 'BLOCK_ARRAY', 'Layout & Sizing', NULL, NULL, 'consts.catalog.block_array.description', 'Array of the two block-axis anchor values (top and bottom). Used by the anchor / positioning system to enumerate vertical placement options without including inline or start/end variants.', 'export const BLOCK_ARRAY: Array<TBlock> = [BLOCK.TOP, BLOCK.BOTTOM]', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/anchor.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('187837d1-199d-491f-839a-8b496fbf3e59', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-textarea-rich', 'useTextareaRich', NULL, 'Textarea', 'mdi-format-text', '', 'Owns the runtime contract of the rich-text textarea (OrigamTextareaRich). Mounts a contenteditable host, applies formatting commands via document.execCommand, tracks active formatting state at the caret for toolbar UI feedback, and sanitises every emit so the consumer v-model never carries XSS payloads. Registers Cmd/Ctrl keyboard shortcuts for the common formatting commands.', NULL, 'function useTextareaRich(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dd92e8d6-ab63-40bf-bfaf-bc73a6874a9f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-text-color', 'useTextColor', NULL, 'Commons', 'mdi-format-color-text', '', 'Foreground-only color helper. Resolves the `color` prop to a utility class (`origam--color-*`) for tokenised intents, or to an inline `color:` declaration for raw CSS values and gradients.', NULL, 'function useTextColor<T extends Record<K, TColor>, K extends string>(
