INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4474b1fc-367c-4ce2-9e0b-373d2edc9cd2', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'composable', 'use-velocity', 'useVelocity', NULL, 'Commons', 'mdi-speedometer', '', 'Tracks touch-event samples per finger (identified by touch.identifier) in circular buffers and computes the instantaneous velocity vector at touchend via impulse-velocity analysis. Used by useTouch to decide whether a fling gesture is fast enough to open or close a drawer.', NULL, 'function useVelocity(): {
