INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('549d2bda-0e00-4a99-b0df-5d72de7cee50', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'interface', 'i-chart-pictorial-slots', 'IChartPictorialSlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pictorial_slots.description', 'Slot signatures exposed by <OrigamChartPictorial>. Extends IChartBaseSlots with a tooltip slot that receives the hovered point, its series and the resolved category label, plus an empty slot rendered when the series array is empty.', 'export interface IChartPictorialSlots extends IChartBaseSlots {
