INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7ea89ae1-0642-4dd9-9ca1-b0ccdea78d20', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'interface', 'i-chart-sankey-props', 'IChartSankeyProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_props.description', 'Props for <OrigamChartSankey>. The component consumes series[0] only — each item in series[0].data must conform to IChartSankeyDatum ({ from, to, value }). Nodes are inferred automatically; columns are assigned by topological depth. Extends IChartBaseProps.', 'export interface IChartSankeyProps extends IChartBaseProps {
