INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1764e62-d298-4adf-b517-be1701ae0b4f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'ec28c1ad-1ea5-4da7-8bf1-93e5db54e724', 'closeConditional', '(e: Event) => boolean', false, 'directives.click_outside.arg_close_conditional', 'Optional guard. The handler fires only when this function returns true. Useful to suppress callbacks while a panel is already closed.', 1, false, NULL, NULL);
