INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d5ab55f-f753-4781-a793-55fcfdc8e044', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'ab8f13f3-cbba-4bc3-a6bb-8f1e859272af', 'start / end / move', '(e: { originalEvent: TouchEvent } & ITouchData) => void', false, 'directives.touch.arg_lifecycle', 'Raw touch lifecycle handlers. The event is augmented with ITouchData (coordinates, delta, velocity, direction).', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('044d9c91-acac-41d1-90af-cda1efe42019', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'ab8f13f3-cbba-4bc3-a6bb-8f1e859272af', 'left / right / up / down', '(e: ITouchData) => void', false, 'directives.touch.arg_swipe', 'Swipe direction handlers. Fired when the touchend velocity and displacement exceed the detection threshold.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ca89e909-bbc9-402f-9c78-356aa67c83ae', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'ab8f13f3-cbba-4bc3-a6bb-8f1e859272af', 'parent', 'boolean', false, 'directives.touch.arg_parent', 'When true, listeners are attached to the parentElement instead of the element itself. Useful for scrollable containers where the element may be smaller than the gesture area.', 2, false, NULL, NULL);
