INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bc1f06cc-4bb6-4d9e-806b-b8df727b5092', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '9599efff-4bd8-4e50-aa73-b43e23c4e7b4', 'callback', NULL, false, 'directives.hover.modifier_callback', 'When present, the directive value is treated as a function (isHovered: boolean) => void instead of a class object.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9665d484-d513-4f06-8897-900bfc427e66', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '9599efff-4bd8-4e50-aa73-b43e23c4e7b4', 'stop', NULL, false, 'directives.hover.modifier_stop', 'Calls stopPropagation() on the underlying pointer events, preventing parent hover handlers from triggering.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7629bd2c-1655-44d2-b62c-fa8e9d588e14', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '173b8f2c-a11d-4a1a-8156-9e3201b86884', 'once', NULL, false, 'directives.intersect.modifier_once', 'Disconnects the observer after the element enters the viewport for the first time. Useful for one-shot animations.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('babcabe2-c461-448a-a43c-bb18c7d85a51', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '173b8f2c-a11d-4a1a-8156-9e3201b86884', 'quiet', NULL, false, 'directives.intersect.modifier_quiet', 'Suppresses the first callback call that IntersectionObserver fires synchronously on setup, so the handler only fires on real scroll-triggered intersections.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87f5c50c-5360-4ec1-a4a0-af8295cc1504', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e1d85a97-df48-4912-8e49-b7ee5884b7c1', 'center', NULL, false, 'directives.ripple.modifier_center', 'The ripple always starts from the geometric center of the element instead of the actual click position. Typically used for icon buttons.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7a791345-12da-474a-9dec-705e7f49b893', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e1d85a97-df48-4912-8e49-b7ee5884b7c1', 'circle', NULL, false, 'directives.ripple.modifier_circle', 'Clips the ripple container to a perfect circle. Combine with .center for round icon buttons.', 1, false, NULL, NULL);
