INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f3c963c3-09cf-4adf-8947-a11fa5c59026', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'c29b9c5c-5c25-42a2-910b-b1c5e0cba45e', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b4e01982-22ea-479e-aea7-269f9628e1c1', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '02be621c-8850-4bf2-a295-89ec89ccab44', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7a01f5a-5503-4cb8-8e1d-ed3e2e918fdd', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '02be621c-8850-4bf2-a295-89ec89ccab44', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34e2d19e-7660-42e6-b2a5-5c92cf1c0a51', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '02be621c-8850-4bf2-a295-89ec89ccab44', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5f1fa961-ba8f-4045-b062-0f4638f9dc6f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'b806a547-32dd-4bcb-8402-7839ac3efc78', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('69c12285-fd80-473c-ac79-cbe58a944d64', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'b806a547-32dd-4bcb-8402-7839ac3efc78', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30edaf2e-bf6d-46d5-ac7a-3cb630b72d77', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'b806a547-32dd-4bcb-8402-7839ac3efc78', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7ba46837-3ad9-41c0-8caf-3ecac8dfa913', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '4ab21030-6ea8-472c-95f7-dcbd2dfc5064', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72bde947-cc3c-4354-80ca-f5aa5337c092', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'c6662df0-072b-409f-92e2-0733d9ebcab1', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8360cd34-d6d1-4143-aece-797558725c23', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '61d3a2e4-87be-4c11-adbf-907f51ccf9c1', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('153f884b-b98e-40a2-a11b-4514961d4284', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '43695c36-ff2c-432b-9e25-286f0d8eeb0e', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
