INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47547d47-fdd3-48ad-b17e-5bce6a10afeb', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '026ad70f-49d2-40e6-9f0c-5fe031a96c67', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "bgColor". Omit when passing a plain Ref.', 1, false, NULL, NULL);
