INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('82ff3502-ace8-445e-be44-bd2e67a344ba', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '85ecddf3-4026-4993-bc03-745fe4548100', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a1145085-e8a9-412d-8f6f-b8b119c7509e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '85ecddf3-4026-4993-bc03-745fe4548100', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('898fd674-771f-4e0d-9f59-493f0db5c90b', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '85ecddf3-4026-4993-bc03-745fe4548100', 'setCurrentDate', '(date: Date) => void', false, NULL, '', 'Optional callback invoked by navigate(). Bind to a v-model:currentDate setter. If omitted, navigation calls have no effect on the parent state.', 2, false, NULL, NULL);
