INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e017ef74-d30e-4316-a660-a2a13c19ac20', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'adb587a6-7896-4cb4-baaa-10573c120d17', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'ref(false)', '', 'Reactive hover state from useHover. When true, resolves the hover color slot (bgHover token rung or -20% darken).', 1, false, NULL, NULL);
