INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30b32793-f3d0-4a2a-8049-ac0592770222', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '231df619-180b-4ac6-8185-97b40484596b', 'options', 'ISheetSwipeOptions', true, NULL, '', 'Configuration object. Includes el (sheet root element ref), handle (drag handle element ref), snapPoints (reactive array of TSheetSnapPoint), defaultSnap (initial snap id), disabled (Ref<boolean> to suspend gesture), and persistent (Ref<boolean> to block the closed snap).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ba84a3ed-0791-4b1e-99cb-c8c32ff810c9', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd1575317-2c36-4ad4-a69d-d09dc37986e6', 'props', 'ISizeProps', true, NULL, '', 'Component props extending ISizeProps. Reads the `size` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('838f2651-dfba-4ece-a283-7c6b5235aa07', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd1575317-2c36-4ad4-a69d-d09dc37986e6', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('24d80581-f54f-4d2e-a0b2-87becc7a177e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'a3639c98-65cf-4a92-a7b7-2ef740a35da8', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f6ac3e8-898c-4185-8714-507379e3d58b', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3955dc-0925-478e-962f-feb3a3a7a2e3', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9040d01f-1a81-480a-a7b3-1fa8a60ad2ae', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd73e007c-3db4-44fe-893b-1c766fa0eafd', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('83a04322-09f0-436f-a02c-156896b8336c', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '940bc82a-275c-4615-b527-7787a4ff7d62', 'id', 'MaybeRefOrGetter<string>', false, 'SNACKBAR_GROUP_DEFAULT_ID', NULL, NULL, 0, false, NULL, NULL);
