INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16108fa7-2dba-4bc2-b687-f2b64e10d446', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'ff137271-22b1-4de2-a4b3-5ce8ab92af98', 'options', '{
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('37799e26-008b-421d-a4eb-19f2e0ed3b93', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e29d0d56-c5cd-43ae-971b-19b424b642b6', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e28787f4-d7be-4cb8-a280-094834cab7f9', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e29d0d56-c5cd-43ae-971b-19b424b642b6', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bfd2fc1-cf79-433e-8f2a-9a6ce6187a8e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e29d0d56-c5cd-43ae-971b-19b424b642b6', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fc1cb33b-84aa-475b-93d3-8bdecd28acd0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0beadd39-4cd1-46f1-a71f-13caff140b08', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0983786a-ee1a-4930-8822-eb437292eb03', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'cd242e33-cfbd-407d-82f2-c2d6604719c8', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('07b0f39d-2cd7-456f-b995-1968ddd63b8f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('63d7d822-43d8-424b-836e-ae7d20ff5a49', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f47b25d-11ab-4389-b2af-e560caf9c2f6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('00067b4e-47cc-4c3a-ba4a-8c7aa54359e3', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d25e4ee-8574-4d2f-a1a9-e57c4f9cac10', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a20ec9c0-36ab-4f39-8a8f-6f095ec6c872', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'f4893819-67bb-4bce-9f82-d72f4dc73777', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('851454a6-7b4d-4623-9435-dd12c54217ca', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'f4893819-67bb-4bce-9f82-d72f4dc73777', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4761901c-490d-4a42-af03-bf6e1e9360ce', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05c56d2d-011d-4d9b-8701-5eb615dbbbc0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ce88a7a-c855-4540-a250-0f4e54b12290', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '646893bb-74cc-4ca4-92bd-474a6d291d5e', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
