INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1480461e-9077-48c8-bfa5-7c42e381bd46', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '646893bb-74cc-4ca4-92bd-474a6d291d5e', 'layoutItemStyles', 'Ref<CSSProperties>', true, NULL, NULL, NULL, 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('971551e0-c642-44b4-86d0-53e379eb69f8', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87a6f99b-3c2b-48e6-8c17-2054ebd767ca', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('35ad6065-a3cb-4f94-bc48-28f027e25a2d', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('088b862b-b4eb-4444-8769-97317e9a94b8', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '49b71666-acb9-41c3-81a4-565607b5ec28', 'css', 'MaybeRef<string>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
