INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a1d9fc6a-d591-4afe-aefe-8123a60d2d61', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '04fe12ae-af59-4a66-838a-925ca63ae1f2', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
