INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d1c33038-fd44-4832-8616-b22f232a0868', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f18dd5f-c664-4e61-92b9-bd72580cebd2', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'dd92e8d6-ab63-40bf-bfaf-bc73a6874a9f', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('70786143-2702-49d4-baf0-0c00cc8db8dc', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'dd92e8d6-ab63-40bf-bfaf-bc73a6874a9f', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e701287d-3ddc-4463-867c-c1440ac6b96f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'bf00ef70-7541-45f6-b738-b5e6a916c78e', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ac824ee-4726-466b-87df-56b3ebc5408f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'bf00ef70-7541-45f6-b738-b5e6a916c78e', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2bb85433-a5f9-4298-bd5b-8cc9c2298c3a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '4ed4813a-4411-439d-bd51-5003115b9c49', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7ad6295d-9875-4227-b085-eb7b7be5cb46', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '4ed4813a-4411-439d-bd51-5003115b9c49', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7a9c0825-2ecd-4231-9a2c-7c0828b54b13', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'cd242e33-cfbd-407d-82f2-c2d6604719c8', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ac9c5c35-4da8-4532-a77c-3db8b46e4ff5', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'cd242e33-cfbd-407d-82f2-c2d6604719c8', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
