INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f32af55-5299-4f34-b495-22004020664d', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
