INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1bcc90c3-9eb4-4463-b2cf-3eb334ae2385', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '95aa2c3a-4156-4586-be53-40f524037657', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
