INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59f666ff-b9a1-4e2a-8304-d0c7eaff9d96', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '54f3549b-d99e-48da-b2c6-c0d52e3c35c8', 'copyable', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Show the copy-to-clipboard button in the top-right corner. Defaults to true.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aa30304f-79e3-4474-8880-51403e6cd1d7', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '54f3549b-d99e-48da-b2c6-c0d52e3c35c8', 'format', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Auto-format the code before highlighting. Reserved for v3 — currently a no-op that warns once in dev.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b95833ce-1637-42a7-b546-a8ef03eeba6e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '54f3549b-d99e-48da-b2c6-c0d52e3c35c8', 'wrap', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Wrap long lines instead of scrolling horizontally. Off by default so the visual column matches the source file.', 6, false, NULL, NULL);
