INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cb8c66e1-0ffa-432f-af78-79d46fa1eea3', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '54f3549b-d99e-48da-b2c6-c0d52e3c35c8', 'compact', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Render the block as a single-line pill — ideal for a copyable install command. Suppresses header, filename and line-numbers.', 8, false, NULL, NULL);
