INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5f715562-5222-4a26-971a-f61b9bf57f52', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '0b76f208-74b9-4f4d-b8b3-fd777b6bad05', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Anchor descriptor that combines a side ("top", "bottom", "left", "right", "center") with an optional alignment ("start", "end"). Controls where the floating content appears relative to its target.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d9a376a1-5ea4-4cea-981d-0a1c3de92a74', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '1e17ebb9-fcfc-4033-8376-098e0446b450', 'locationStrategy', 'TLocationStrategy | TLocationStrategyFn', NULL, NULL, true, NULL, NULL, NULL, 'Named strategy ("connected" | "static") or a custom strategy function. The connected strategy aligns the floating panel to the activator; static keeps it in place.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('11974d47-ac39-4a4d-a68d-7f212ec7861f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '1e17ebb9-fcfc-4033-8376-098e0446b450', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21e6f2fe-de92-41b5-81d2-b28ad1de64be', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '1e17ebb9-fcfc-4033-8376-098e0446b450', 'origin', 'TAnchor | ''auto'' | ''overlap''', NULL, NULL, true, NULL, NULL, NULL, 'The anchor point on the floating content itself. "auto" mirrors the location; "overlap" places the panel over the activator.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f6b562b-7266-4882-91d5-81ecfa91bb86', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '1e17ebb9-fcfc-4033-8376-098e0446b450', 'offset', 'number | string | Array<number>', NULL, NULL, true, NULL, NULL, NULL, 'Gap in pixels between the activator and the floating content. An array of two values sets [main-axis, cross-axis] offsets independently.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('444298c0-44ff-46ff-b887-85d8e24eaecb', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', '1e17ebb9-fcfc-4033-8376-098e0446b450', 'viewportMargin', 'number', NULL, NULL, true, NULL, '12', NULL, 'Minimum breathing room in pixels between the floating content and each viewport edge. Defaults to 12 so panels never overlap browser chrome.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3b869d23-bb3c-4673-8e17-d4d1bd417394', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'd3a37ced-e5b3-4bff-9adb-e39b34554c3a', 'contentEl', 'Ref<HTMLElement | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the floating content element. The strategy reads its dimensions and writes its position here.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c65783c9-3167-495e-a201-caf872859fc4', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'd3a37ced-e5b3-4bff-9adb-e39b34554c3a', 'target', 'Ref<HTMLElement | [x: number, y: number] | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the anchor element or an [x, y] pixel coordinate. When set to coordinates, the floating panel anchors to a virtual point (used by context menus).', 1, false, NULL, NULL);
