INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('12d6f8e0-4a84-45a3-830d-8605dbc40a4b', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'lang', 'TCodeLangOpen', 'code-lang', 'type', NULL, false, '''plaintext''', 'components.code.props.lang.description', 'Language grammar to apply. Supported: ''plaintext'' | ''vue'' | ''ts'' | ''js'' | ''tsx'' | ''jsx'' | ''scss'' | ''css'' | ''json'' | ''bash'' | ''html'' | ''xml'' | ''yaml'' | ''md''. Unknown values fall back to plaintext.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4d5c0e92-7e91-40d7-82b9-8ed4510f4598', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db57ce48-1bc5-4ea6-87d7-0008bc68da01', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('03c3f7e4-4eaf-470b-9a01-a0d03390c98e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a18af0ad-aaaa-4037-b670-2d954060fa2a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ec45a556-3988-4d48-bb4b-4765dd4854cc', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('80dfb546-f978-4ac6-8ae8-78a3b8fd818d', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('766d810f-afaf-48f1-b48a-67a45b10eacc', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49a617ce-a86a-44ad-8f5f-c52604cb7fb1', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:41:05.755695+00', 'c9b3159a-6447-4faf-a588-3bd4ce0f17a4', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
