INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('557b55aa-dd0b-43c3-b4dd-6f0ee4902cd0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd1575317-2c36-4ad4-a69d-d09dc37986e6', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d778b5b-817b-46c0-82e4-045e36ad094f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd1575317-2c36-4ad4-a69d-d09dc37986e6', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d20ed24-0adc-4070-adcc-2213b616a3e8', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'a3639c98-65cf-4a92-a7b7-2ef740a35da8', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a44abe6-9be5-4b83-8d95-4f21f0eb435b', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'a3639c98-65cf-4a92-a7b7-2ef740a35da8', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('020a6a42-d8eb-4bd4-9902-624ace7cad57', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'a3639c98-65cf-4a92-a7b7-2ef740a35da8', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4c5823a5-dcac-42fe-9f0d-e28f8f4085d9', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'a3639c98-65cf-4a92-a7b7-2ef740a35da8', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('abaaa602-8bf6-4e63-aabe-637c33a20f6a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'a3639c98-65cf-4a92-a7b7-2ef740a35da8', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('220c95c0-afa8-4a8e-aede-e577bbaeec65', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3955dc-0925-478e-962f-feb3a3a7a2e3', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c26cbbbc-332e-4980-bf4b-0d52f6af461e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3955dc-0925-478e-962f-feb3a3a7a2e3', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a4b48216-ade1-431e-a4b1-8ce0e47a8228', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3955dc-0925-478e-962f-feb3a3a7a2e3', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('215c8a59-4771-4496-b707-5c99a393521d', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3955dc-0925-478e-962f-feb3a3a7a2e3', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a69ecfbb-7027-4356-ab68-362250472806', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd73e007c-3db4-44fe-893b-1c766fa0eafd', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e33ab1fb-45f3-4739-9d86-99524e7cf373', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd73e007c-3db4-44fe-893b-1c766fa0eafd', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ec6dffc3-886e-4148-bab9-2a0ef0e52cc7', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd73e007c-3db4-44fe-893b-1c766fa0eafd', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bdf8d5cf-e570-419a-aa65-c08aa211c257', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'd73e007c-3db4-44fe-893b-1c766fa0eafd', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d284c089-d8e4-40de-835a-ea50aadf3b8a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'fb375c70-6ad6-42e8-9fa1-f9620a8c6058', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce1b2bc9-f03f-47de-9df6-46f4e7b779d3', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'fb375c70-6ad6-42e8-9fa1-f9620a8c6058', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c4e3801a-ffe3-480a-9bd9-4c36307b7869', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'fb375c70-6ad6-42e8-9fa1-f9620a8c6058', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d8dceab-0682-4154-bace-97ec1139b4ef', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '48191bc9-805d-4952-a274-b918016dccc2', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da85b643-1bf5-42b7-a5f7-2a5b071d2260', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '48191bc9-805d-4952-a274-b918016dccc2', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9370f9d5-e142-47c8-a4a6-47c492e3a1e0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '90447013-f669-4d6b-9fff-45e2503ed856', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('60ccf052-c618-4ca4-bf25-2b20863f51c6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e29d0d56-c5cd-43ae-971b-19b424b642b6', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8e3c3786-f3e1-4124-93bf-5956bfbff92d', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e29d0d56-c5cd-43ae-971b-19b424b642b6', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('56f4ca53-2a69-4329-a4d8-58577feb85cb', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'e29d0d56-c5cd-43ae-971b-19b424b642b6', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d9282c93-9d75-4dab-9824-42c96ff9e242', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c0cebe05-c36d-4c4c-bbef-9501ce2108dc', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3218ead5-f064-4f56-a68b-b55ab86352d0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51c483f9-3614-424f-8ac0-731e26d38d18', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d4529a1-c505-4a5f-9ebe-aea542a6c734', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05510e0f-5dad-4e0a-998e-fed6a394f2d8', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92a85cb9-89eb-462e-84fc-df1da89c50a3', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '462afbd8-7a5a-4efd-b951-feda927f3bd6', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6c015a2-7479-45d5-b214-b72954af4334', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aecabf05-521b-4c2a-a3d5-f7692840e7d5', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab98ed8f-2387-4ad6-a716-3f4468d7e333', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e39005dc-33a7-43dd-abd7-6af79c573b04', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c3abe2f8-2464-40b9-bb2f-2b81ad8b512a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51a21cda-6f3c-445f-9504-ba5b1e40735f', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('679b836f-7c5e-4465-88a0-f1d3602a6c21', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '646893bb-74cc-4ca4-92bd-474a6d291d5e', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a6149712-0075-4f18-82c3-01bcf8e4c9aa', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '646893bb-74cc-4ca4-92bd-474a6d291d5e', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('120bb87e-1556-4d04-b820-c5e275f197c9', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1596a8e8-838d-4d35-ab6e-33f1235abf88', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('be0ac4a2-ded8-4357-952b-fbaf452364c0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9c1224fa-580f-4a3e-97bd-b64ba43859d2', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '258367ed-d37d-4126-b182-1cf52955ad07', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('43d0984a-0fd8-4922-b4e9-e750413686d0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '04fe12ae-af59-4a66-838a-925ca63ae1f2', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b613eda2-41ca-46f9-b32b-f44cb84e1a02', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1bfd5b1a-8e8a-4403-8224-33bd743cb9f6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3401ce5d-8fca-4b62-80d6-84ac1252e766', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bef5fd76-cd9d-47aa-844b-f44718a47c3c', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a3e891b0-4a50-41bd-8cfd-805e932f87dd', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fa85f45c-3788-44bf-9ac7-12f24bc17066', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '187837d1-199d-491f-839a-8b496fbf3e59', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('68fc0000-cef0-4c84-bc75-5263f9ea893f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'dd92e8d6-ab63-40bf-bfaf-bc73a6874a9f', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1b26779f-ead2-47af-af20-02e3f9fbf268', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', 'dd92e8d6-ab63-40bf-bfaf-bc73a6874a9f', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('77396e3f-1417-4297-9602-cc37ebce3ca7', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '0e0142bb-fa52-445c-880c-425309d7f464', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
