INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51d95487-2493-4691-82b9-a23b515e88ea', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '51772967-793a-4a15-8ab9-56a4a5381e85', 'variantClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--variant-{variant}` when a variant is set, empty array otherwise. Bind to the component root via `:class`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a22bf2f6-3d48-40de-acce-d2e19d474974', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '4474b1fc-367c-4ce2-9e0b-373d2edc9cd2', 'addMovement', '(e: TouchEvent) => void', '', 'Record a touchstart or touchmove event sample. Each touch point is tracked independently. Call this on every touchmove to build a time-stamped sample history.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cf3be564-2643-44f6-929a-b0982ace632a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '4474b1fc-367c-4ce2-9e0b-373d2edc9cd2', 'endTouch', '(e: TouchEvent) => void', '', 'Clear the circular buffer for all changed touches. Call at touchstart before starting a new gesture to discard leftover samples from a previous interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('079ae041-586d-4dac-8957-795178c49d78', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '4474b1fc-367c-4ce2-9e0b-373d2edc9cd2', 'getVelocity', '(id: number) => { x: number; y: number; direction: string }', '', 'Compute the velocity vector for the given touch identifier from the recent sample history. Returns px/ms values for x and y axes and the dominant direction string. Throws if no samples are found for the id.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef2ae9bd-a43b-4f9e-b35c-0b8e6d86368b', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '62ccd82d-5835-48ce-95a0-eb052a13d972', 'videoRef', 'Ref<HTMLVideoElement | null>', '', 'Template ref to bind to the `<video>` element. Reused from `options.videoRef` when provided.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('28646e3c-c389-45e4-b81f-b3a6d81319dd', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '62ccd82d-5835-48ce-95a0-eb052a13d972', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('406a0b1d-5222-4155-842d-b2fbd66fdfcc', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '62ccd82d-5835-48ce-95a0-eb052a13d972', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16b78c94-ff33-4049-92e2-1d2231e5633a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('792f35d9-2532-4fa2-80f5-0fe1f14b4de6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04da13b8-e5f7-47a6-a06c-a0f0f21f5ab4', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05b46a8c-2e9d-4779-b6f2-7dfacb12369a', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('018e9453-dd19-49fa-8009-30c9d1214548', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c3fe5f5-69fb-42c7-8c08-44870c741483', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a835292f-eb80-47a6-a370-f5fc955ad5c5', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a720005-7dd8-4e49-89cc-f08e72e41d8c', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c34ac6a1-33b1-4d4d-a893-205695c7ecef', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '6ef00a55-9f23-4ece-a4b2-c405b3227cd3', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f3f4159-3be3-4c4e-8499-39287be8cccd', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '95aa2c3a-4156-4586-be53-40f524037657', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('18c6fa89-fb92-4780-90f1-b583db9fb8ed', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8bb3334f-491c-41a5-a4de-6a4d2f666ae9', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8dde306d-e984-459a-9608-9b20bdd243d6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8bb3334f-491c-41a5-a4de-6a4d2f666ae9', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e0c03e72-3322-4b99-9caf-e5d2f99bab34', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8bb3334f-491c-41a5-a4de-6a4d2f666ae9', 'uninstall', '() => void', '', 'Remove the injected layer and disconnect the MutationObserver if active. Called automatically on scope dispose.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('40d8567c-ad79-4202-8546-61a7b6b29144', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '1b319c25-9883-4bd5-8664-4d6998475b9d', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e678868b-4edb-4a02-8c13-46d0d5785c9e', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '1b319c25-9883-4bd5-8664-4d6998475b9d', 'isComputing', 'Ref<boolean>', '', 'True while the fetch + decode round-trip is in progress. Use to render a skeleton or loading indicator.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b88eabd-c5c9-46c3-a7cd-d2be385ed981', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '1b319c25-9883-4bd5-8664-4d6998475b9d', 'error', 'Ref<Error | null>', '', 'Captures fetch errors (non-2xx response), decode errors (corrupt / unsupported audio), and OfflineAudioContext unavailability. null when no error.', 2, false, NULL, NULL);
