INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d3d3ae68-f82f-4f4e-b3ba-8ac8f6aadad6', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3fee63-4360-417a-ad00-e019d829a5e3', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cb364c6-f677-4046-b1b4-2ef6016c9232', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3fee63-4360-417a-ad00-e019d829a5e3', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92c151c2-fb11-47a8-88f5-7d2f2e9e380f', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '8e3fee63-4360-417a-ad00-e019d829a5e3', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ffce2d1-bfdf-4a21-a9cf-7c91b6686bb0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '7cd35ec4-2abf-4af7-8556-05f7a558344e', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aca138b7-b864-495a-897a-fbe9b91ed1b3', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '7cd35ec4-2abf-4af7-8556-05f7a558344e', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('18256a82-3275-4336-bdac-71ddef15f1c0', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '7cd35ec4-2abf-4af7-8556-05f7a558344e', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36a6635f-d84b-4897-8c6c-d8e25567bdbe', '2026-10-22 17:40:37.250043+00', '2026-10-22 17:40:37.250043+00', '7cd35ec4-2abf-4af7-8556-05f7a558344e', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
